-- Schema generated by Store at 48f1a26d15d70093377ef646d56592c72a0f0a9e; no service data.
CREATE TABLE assignments (request_id TEXT PRIMARY KEY, payload TEXT NOT NULL, payload_hash TEXT NOT NULL, thread_id TEXT NOT NULL, environment_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', created_at TEXT NOT NULL, cancelled_at TEXT, owner_hash TEXT, review INTEGER NOT NULL DEFAULT 0, delivery TEXT, priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('normal','background')), objective_key TEXT, revision TEXT, task_kind TEXT, source TEXT CHECK(source IN ('drainer','dot-fix','agent','unknown')), valid_until TEXT, cancelled_reason TEXT, listed_count INTEGER NOT NULL DEFAULT 0, last_listed_at TEXT, skipped_by_dot_at TEXT, last_seen_listed_at TEXT, eligible_since TEXT, passed_over INTEGER NOT NULL DEFAULT 0, target_worker TEXT NOT NULL DEFAULT 'dot');
CREATE TABLE claims (request_id TEXT PRIMARY KEY REFERENCES assignments(request_id), claimant TEXT NOT NULL, claim_id TEXT NOT NULL UNIQUE, claimed_at TEXT NOT NULL, subject TEXT NOT NULL DEFAULT 'local-principal', last_progress_at TEXT, last_claim_activity_at TEXT, last_seen_note_seq INTEGER NOT NULL DEFAULT 0, epoch INTEGER NOT NULL DEFAULT 1, state TEXT NOT NULL DEFAULT 'active' CHECK(state IN ('active','abandoned')), abandoned_at TEXT, abandon_reason TEXT, worker TEXT NOT NULL DEFAULT 'dot');
CREATE TABLE progress (id INTEGER PRIMARY KEY, request_id TEXT NOT NULL REFERENCES assignments(request_id), note TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE reports (request_id TEXT PRIMARY KEY REFERENCES assignments(request_id), claim_id TEXT NOT NULL, outcome TEXT NOT NULL, summary TEXT NOT NULL, result TEXT NOT NULL, receipt_id TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, late INTEGER NOT NULL DEFAULT 0, workspace_evidence TEXT, worker TEXT NOT NULL DEFAULT 'dot');
CREATE TABLE subscriptions (id TEXT PRIMARY KEY, principal TEXT NOT NULL, url TEXT NOT NULL, args TEXT NOT NULL, secret TEXT NOT NULL, expires_at TEXT NOT NULL, verified_at TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'active', last_event_2xx_at TEXT, auth_failures INTEGER NOT NULL DEFAULT 0, rotation_blocked INTEGER NOT NULL DEFAULT 0, worker TEXT NOT NULL DEFAULT 'dot');
CREATE TABLE messages (message_id TEXT PRIMARY KEY, text TEXT NOT NULL, text_sha256 TEXT NOT NULL, preview TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL, acknowledged_at TEXT, target_worker TEXT NOT NULL DEFAULT 'dot');
CREATE TABLE watches (request_id TEXT PRIMARY KEY REFERENCES assignments(request_id), deadline TEXT NOT NULL, state TEXT NOT NULL, updated_at TEXT NOT NULL, notification_id TEXT);
CREATE TABLE operator_state (id INTEGER PRIMARY KEY CHECK(id=1), paused_at TEXT, reason TEXT);
CREATE TABLE alert_episodes (condition TEXT PRIMARY KEY, active INTEGER NOT NULL, started_at TEXT, last_change_at TEXT NOT NULL);
CREATE TABLE workspaces (request_id TEXT PRIMARY KEY REFERENCES assignments(request_id), claim_id TEXT NOT NULL, base_sha TEXT NOT NULL, path TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, initial_patch_applied INTEGER NOT NULL DEFAULT 0, fetched_at TEXT);
CREATE TABLE check_runs (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES assignments(request_id), claim_id TEXT NOT NULL, check_id TEXT NOT NULL, exit_code INTEGER, timed_out INTEGER NOT NULL, output_artifact_id TEXT NOT NULL, output_sha256 TEXT NOT NULL, duration_ms INTEGER NOT NULL, created_at TEXT NOT NULL, diff_sha256 TEXT, phase TEXT NOT NULL DEFAULT 'check');
CREATE TABLE assignment_reannouncements (request_id TEXT NOT NULL REFERENCES assignments(request_id), subscription_id TEXT NOT NULL REFERENCES subscriptions(id), count INTEGER NOT NULL DEFAULT 0, last_announced_at TEXT NOT NULL, next_due_at INTEGER, PRIMARY KEY(request_id, subscription_id));
CREATE INDEX messages_pending ON messages(status,created_at);
CREATE TABLE t3_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL, call_id TEXT NOT NULL, subject TEXT NOT NULL, tool TEXT NOT NULL, args_summary TEXT NOT NULL, text_sha256 TEXT, text_preview TEXT, result_status TEXT NOT NULL, t3_ids TEXT NOT NULL DEFAULT '{}');
CREATE INDEX t3_audit_at ON t3_audit(at);
CREATE TRIGGER t3_audit_no_update BEFORE UPDATE ON t3_audit BEGIN SELECT RAISE(ABORT, 't3 audit is append-only'); END;
CREATE TRIGGER t3_audit_no_delete BEFORE DELETE ON t3_audit BEGIN SELECT RAISE(ABORT, 't3 audit is append-only'); END;
CREATE TABLE IF NOT EXISTS "notifications" (id TEXT PRIMARY KEY, kind TEXT NOT NULL, request_id TEXT REFERENCES assignments(request_id), subscription_id TEXT, body TEXT, state TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_at INTEGER NOT NULL DEFAULT 0, last_error TEXT, argv TEXT, created_at TEXT NOT NULL, attempt_started_at TEXT, attempt_id TEXT, last_reconciled_at TEXT, uncertain_reason TEXT, message_id TEXT REFERENCES messages(message_id), covers TEXT, wake_kind TEXT CHECK(wake_kind IN ('submit','rewake','owner_note','message')));
CREATE INDEX notifications_due ON notifications(state,next_at);
CREATE TABLE check_jobs (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES assignments(request_id), claim_id TEXT NOT NULL, check_id TEXT NOT NULL, diff_sha256 TEXT NOT NULL, status TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, error TEXT, output_preview TEXT);
CREATE INDEX check_jobs_request ON check_jobs(request_id,started_at);
CREATE TABLE owner_notes (sequence INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, request_id TEXT NOT NULL REFERENCES assignments(request_id), at TEXT NOT NULL, text TEXT NOT NULL);
CREATE INDEX owner_notes_request ON owner_notes(request_id,sequence);
CREATE TRIGGER owner_notes_no_update BEFORE UPDATE ON owner_notes BEGIN SELECT RAISE(ABORT, 'owner notes are append-only'); END;
CREATE TRIGGER owner_notes_no_delete BEFORE DELETE ON owner_notes BEGIN SELECT RAISE(ABORT, 'owner notes are append-only'); END;
CREATE TABLE worker_activity (subject TEXT PRIMARY KEY, last_call_at TEXT NOT NULL, last_list_pending_at TEXT);
CREATE TABLE alert_cursors (name TEXT PRIMARY KEY, value INTEGER NOT NULL);
CREATE TABLE assignment_delivery_mutes (request_id TEXT PRIMARY KEY REFERENCES assignments(request_id), muted_at TEXT NOT NULL);
CREATE TABLE pr_preflights (request_id TEXT NOT NULL REFERENCES assignments(request_id), phase TEXT NOT NULL CHECK(phase IN ('submit','claim')), evidence TEXT NOT NULL, PRIMARY KEY(request_id,phase));
CREATE INDEX assignments_pending_priority ON assignments(status,priority,created_at);
CREATE TABLE lifecycle_events (id INTEGER PRIMARY KEY AUTOINCREMENT, request_id TEXT NOT NULL, claim_id TEXT, epoch INTEGER, type TEXT NOT NULL CHECK(type IN ('queued','claimed','working','waiting','blocked','completed','consumed','accepted','integrated','abandoned','cancelled','delivery_sent','delivery_uncertain','reconciled','check_started','check_passed','check_failed','check_skipped')), at TEXT NOT NULL, actor TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN ('live','backfill')), reason TEXT);
CREATE INDEX lifecycle_events_request ON lifecycle_events(request_id,id);
CREATE INDEX lifecycle_events_type_at ON lifecycle_events(type,at);
CREATE TABLE lifecycle_daily (day TEXT NOT NULL, type TEXT NOT NULL, kind TEXT NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(day,type,kind));
CREATE TABLE lifecycle_retention (id INTEGER PRIMARY KEY CHECK(id=1), cutoff TEXT, rolled_up_before TEXT);
CREATE TRIGGER lifecycle_events_no_update BEFORE UPDATE ON lifecycle_events BEGIN SELECT RAISE(ABORT, 'lifecycle events are append-only'); END;
CREATE TRIGGER lifecycle_events_no_delete BEFORE DELETE ON lifecycle_events WHEN NOT EXISTS (SELECT 1 FROM lifecycle_retention WHERE id=1 AND cutoff IS NOT NULL AND old.at<cutoff) BEGIN SELECT RAISE(ABORT, 'lifecycle events are append-only'); END;
CREATE INDEX assignments_objective ON assignments(objective_key,created_at);
CREATE INDEX notifications_request_state ON notifications(request_id,state);
CREATE INDEX notifications_wake_gate ON notifications(subscription_id,state) WHERE wake_kind IN ('submit','rewake');
CREATE INDEX notifications_wake_time ON notifications(subscription_id,state,COALESCE(attempt_started_at,created_at)) WHERE wake_kind IN ('submit','rewake','owner_note');
CREATE INDEX notifications_wake_latest ON notifications(request_id,subscription_id,created_at) WHERE wake_kind IN ('submit','rewake');
CREATE TABLE dot_breaks (id INTEGER PRIMARY KEY AUTOINCREMENT, since TEXT NOT NULL, until TEXT, reason TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN ('owner','inferred')), end_source TEXT CHECK(end_source IN ('tool_call','owner')), usage TEXT NOT NULL, last_probe_at TEXT, start_alerted_at TEXT, end_alerted_at TEXT, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX dot_breaks_one_active ON dot_breaks(COALESCE(until,'')) WHERE until IS NULL;
CREATE TABLE break_notices (break_id INTEGER NOT NULL REFERENCES dot_breaks(id), target TEXT NOT NULL, request_ids TEXT NOT NULL, notification_id TEXT, created_at TEXT NOT NULL, PRIMARY KEY(break_id,target));
CREATE TABLE IF NOT EXISTS "worker_calls" (subject TEXT NOT NULL, minute INTEGER NOT NULL, tool TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, bytes INTEGER, PRIMARY KEY(subject,minute,tool));
CREATE INDEX worker_calls_minute ON worker_calls(minute);
CREATE INDEX assignments_expiry ON assignments(status,valid_until);
CREATE TABLE IF NOT EXISTS "learned_limits" (name TEXT PRIMARY KEY CHECK(name IN ('response_bytes_per_hour','response_bytes_per_24h','tool_calls_per_hour','tool_calls_per_24h','claims_per_hour')), value INTEGER NOT NULL, break_id INTEGER, ledger_bytes INTEGER NOT NULL, at TEXT NOT NULL);
CREATE TABLE claim_denials (request_id TEXT PRIMARY KEY REFERENCES assignments(request_id), at TEXT NOT NULL, reported_in TEXT NOT NULL, capacity INTEGER NOT NULL, note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "artifacts" (id TEXT NOT NULL, request_id TEXT NOT NULL REFERENCES assignments(request_id), claim_id TEXT NOT NULL, kind TEXT NOT NULL, path TEXT NOT NULL UNIQUE, size INTEGER NOT NULL, sha256 TEXT, sealed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, retention_until TEXT, PRIMARY KEY(request_id,id));
